@Entity
public class MedicalRecord {
    @NotBlank(message = "主诉不能为空")
    private String chiefComplaint;

    @NotBlank(message = "现病史不能为空")
    private String presentIllness;

    @NotBlank(message = "诊断不能为空")
    private String diagnosis;
}

// 使用规则引擎
@Autowired
private QualityControlRuleEngine ruleEngine;

public QualityScore calculateScore(MedicalRecord record) {
    return ruleEngine.evaluate(record);
}

public void checkAdmissionRecordTiming(Patient patient) {
    LocalDateTime admissionTime = patient.getAdmissionTime();
    LocalDateTime recordTime = patient.getAdmissionRecordTime();

    if (recordTime == null || 
        Duration.between(admissionTime, recordTime).toHours() > 24) {
        qcAlertService.alertTimingViolation(patient);
    }
}

public boolean verifySignature(MedicalRecord record, DigitalSignature signature) {
    return caService.verify(
        record.getContent(),
        signature.getValue(),
        signature.getCertificate()
    );
}
